CREATE TYPE "MarketplaceSignalSource" AS ENUM ('OBSERVED','DERIVED','PREDICTED');
CREATE TYPE "MarketplaceLiquidityWindow" AS ENUM ('DAILY','WEEKLY','ROLLING_7_DAYS','ROLLING_30_DAYS','ROLLING_90_DAYS');
CREATE TYPE "MarketplaceLiquidityHealth" AS ENUM ('HEALTHY','DEMAND_CONSTRAINED','SUPPLY_CONSTRAINED','CAPACITY_CONSTRAINED','MATCH_CONSTRAINED','TRUST_CONSTRAINED','DATA_INSUFFICIENT');
CREATE TABLE "MarketplaceLiquidityProfile" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE,"version" INTEGER NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceDemandSignal" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"signalType" TEXT NOT NULL,"source" "MarketplaceSignalSource" NOT NULL,"sourceEntityType" TEXT NOT NULL,"sourceEntityId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"categoryId" TEXT,"serviceId" TEXT,"geoKey" TEXT,"timeWindow" "MarketplaceLiquidityWindow" NOT NULL,"value" DECIMAL(16,4) NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"freshness" DECIMAL(5,4) NOT NULL,"dataState" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceSupplySignal" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"signalType" TEXT NOT NULL,"source" "MarketplaceSignalSource" NOT NULL,"sourceEntityType" TEXT NOT NULL,"sourceEntityId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"categoryId" TEXT,"serviceId" TEXT,"geoKey" TEXT,"timeWindow" "MarketplaceLiquidityWindow" NOT NULL,"value" DECIMAL(16,4) NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"freshness" DECIMAL(5,4) NOT NULL,"dataState" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceCapacityObservation" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"serviceId" TEXT,"professionalId" TEXT,"geoKey" TEXT,"timeWindow" "MarketplaceLiquidityWindow" NOT NULL,"availableSlots" INTEGER NOT NULL,"usableMinutes" INTEGER NOT NULL,"bookedMinutes" INTEGER NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"freshness" DECIMAL(5,4) NOT NULL,"dataState" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceLiquiditySnapshot" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"window" "MarketplaceLiquidityWindow" NOT NULL,"periodStart" TIMESTAMP(3) NOT NULL,"periodEnd" TIMESTAMP(3) NOT NULL,"health" "MarketplaceLiquidityHealth" NOT NULL,"dataState" TEXT NOT NULL,"components" JSONB NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"version" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceSupplyGap" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"snapshotId" TEXT NOT NULL,"categoryId" TEXT,"serviceId" TEXT,"geoKey" TEXT,"timeWindow" "MarketplaceLiquidityWindow" NOT NULL,"severity" TEXT NOT NULL,"demandEvidence" JSONB NOT NULL,"supplyEvidence" JSONB NOT NULL,"evidence" JSONB NOT NULL,"limitations" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("snapshotId") REFERENCES "MarketplaceLiquiditySnapshot"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceSupplyOpportunity" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"gapId" TEXT NOT NULL,"categoryId" TEXT,"serviceId" TEXT,"geoKey" TEXT,"timeWindow" "MarketplaceLiquidityWindow" NOT NULL,"evidence" JSONB NOT NULL,"limitations" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("gapId") REFERENCES "MarketplaceSupplyGap"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceNetworkSignal" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"signalType" TEXT NOT NULL,"relationType" TEXT NOT NULL,"evidence" JSONB NOT NULL,"confidence" DECIMAL(5,4) NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"calculationVersion" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE);
CREATE TABLE "MarketplaceLiquidityVersion" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL,"snapshotId" TEXT NOT NULL UNIQUE,"version" INTEGER NOT NULL,"calculationVersion" TEXT NOT NULL,"summary" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY("businessId") REFERENCES "Business"("id") ON DELETE CASCADE,FOREIGN KEY("snapshotId") REFERENCES "MarketplaceLiquiditySnapshot"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "MarketplaceDemandSignal_businessId_idempotencyKey_key" ON "MarketplaceDemandSignal"("businessId","idempotencyKey"); CREATE INDEX "MarketplaceDemandSignal_scope_idx" ON "MarketplaceDemandSignal"("businessId","categoryId","serviceId","geoKey","timeWindow");
CREATE UNIQUE INDEX "MarketplaceSupplySignal_businessId_idempotencyKey_key" ON "MarketplaceSupplySignal"("businessId","idempotencyKey"); CREATE INDEX "MarketplaceSupplySignal_scope_idx" ON "MarketplaceSupplySignal"("businessId","categoryId","serviceId","geoKey","timeWindow");
CREATE UNIQUE INDEX "MarketplaceCapacityObservation_businessId_idempotencyKey_key" ON "MarketplaceCapacityObservation"("businessId","idempotencyKey"); CREATE INDEX "MarketplaceCapacityObservation_scope_idx" ON "MarketplaceCapacityObservation"("businessId","serviceId","professionalId","observedAt");
CREATE UNIQUE INDEX "MarketplaceLiquiditySnapshot_businessId_version_key" ON "MarketplaceLiquiditySnapshot"("businessId","version"); CREATE INDEX "MarketplaceLiquiditySnapshot_window_idx" ON "MarketplaceLiquiditySnapshot"("businessId","window","observedAt");
CREATE INDEX "MarketplaceSupplyGap_scope_idx" ON "MarketplaceSupplyGap"("businessId","categoryId","serviceId","geoKey","observedAt"); CREATE INDEX "MarketplaceSupplyOpportunity_scope_idx" ON "MarketplaceSupplyOpportunity"("businessId","categoryId","serviceId","geoKey","observedAt");
CREATE INDEX "MarketplaceNetworkSignal_type_idx" ON "MarketplaceNetworkSignal"("businessId","signalType","observedAt"); CREATE UNIQUE INDEX "MarketplaceLiquidityVersion_businessId_version_key" ON "MarketplaceLiquidityVersion"("businessId","version");
CREATE INDEX "MarketplaceDemandSignal_businessId_signalType_observedAt_idx" ON "MarketplaceDemandSignal"("businessId","signalType","observedAt");
CREATE INDEX "MarketplaceSupplySignal_businessId_signalType_observedAt_idx" ON "MarketplaceSupplySignal"("businessId","signalType","observedAt");
CREATE INDEX "MarketplaceCapacityObservation_businessId_geoKey_timeWindow_idx" ON "MarketplaceCapacityObservation"("businessId","geoKey","timeWindow");
CREATE INDEX "MarketplaceSupplyGap_businessId_snapshotId_idx" ON "MarketplaceSupplyGap"("businessId","snapshotId");
CREATE INDEX "MarketplaceLiquidityVersion_businessId_createdAt_idx" ON "MarketplaceLiquidityVersion"("businessId","createdAt");
